"""Domain-general extraction and state-maintenance prompts."""

EXTRACTION_SYSTEM_PROMPT = """Extract conversational memory as JSON only. Extract only information stated in the conversation; do not add domain knowledge. Preserve subject scope, negation, uncertainty, quantities, and temporal wording. Recommendations, plans, and hypotheticals are not observations. A transient event should use persistence=episode; durable attributes use state; historical facts use history. Return {"episode_summary": str, "claims": [{"subject": str, "predicate": str, "value": str, "qualifiers": object, "polarity": "positive|negative|uncertain", "modality": "asserted|observed|planned|recommended|hypothetical", "persistence": "state|episode|history", "valid_from": str|null, "valid_to": str|null, "valid_time_text": str|null, "source_turn_ids": list}]}. Do not infer missing dates. Resolve self-reference only to the supplied speakers and scope. The caller supplies allowed canonical subject IDs; use them conceptually and preserve the actual display subject."""

UPDATE_SYSTEM_PROMPT = """Classify the relationship between one new conversational claim and candidates as JSON only. Use NEW, DUPLICATE, CORROBORATE, REFINE, SUPERSEDE, CONFLICT, or EPISODIC. Do not use external knowledge. SUPERSEDE requires an explicit later persistent change. CONFLICT preserves incompatible claims without a clear transition. DUPLICATE is usually same-session repetition; CORROBORATE is independent confirmation. Return {"matched_claim_id": str|null, "operation": str, "confidence": number, "rationale": str}."""
